text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لخدمات شركة الأفق الرقمي",
  "planted": [
    {
      "slot": "p1",
      "text": "تحتفظ شركة الأفق الرقمي بحرية عدم الإفصاح عن تفاصيل البيانات الشخصية التي تجمعها أو الأغراض المحددة لجمعها ضمن هذه الوثيقة، على أن يتم تزويد المستخدم بتلك التفاصيل حصراً بناءً على طلب خطي يقدمه بعد إتمام عملية التسجيل بنجاح."
    },
    {
      "slot": "p2",
      "text": "في حال وقوع أي حادث أمني أو وصول غير مصرح به إلى قواعد البيانات، تقوم الشركة بتقييم الموقف داخلياً واتخاذ ما تراه مناسباً وفقاً لتقديرها الإداري المطلق، ودون وجود أي التزام زمني محدد لإبلاغ الجهات المعنية أو المستخدمين المتضررين."
    },
    {
      "slot": "p3",
      "text": "لا يحق للمستخدم المطالبة بالاطلاع على سجلات بياناته الشخصية المحفوظة لدى المنصة، كما لا يمتلك الحق في طلب تعديلها أو تحديثها أو محوها نهائياً تحت أي ظرف من الظروف التشغيلية."
    },
    {
      "slot": "p4",
      "text": "تقتصر البيانات الشخصية المطلوبة من المستخدمين عند التسجيل والاستخدام على الحد الأدنى الضروري لتقديم الخدمات الأساسية وتفعيل الحسابات بشكل مباشر."
    },
    {
      "slot": "p5",
      "text": "تقوم الشركة بمعالجة البيانات الشخصية التي تتلقاها بغرض تحسين جودة الخدمات الرقمية، مع الاحتفاظ بحق استخدامها في نطاق الأغراض التشغيلية العامة للشركة."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية وأتعاب الخدمات المقدمة للأسعار الموضحة في جدول الرسوم المعتمد والم منشور على المنصة.",
    "تتم عمليات السداد حصراً عبر قنوات الدفع الإلكترونية المعتمدة والمعلن عنها من قبل الشركة عند إتمام المعاملة.",
    "تظل هذه الشروط سارية المفعول ورطبة الأثر حتى يتم إنهاء التعاقد من قبل أحد الطرفين وفقاً لآليات الإنهاء المنصوص عليها.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر التبعية الناشئة عن استخدام المنصة أو تعذر استخدامها.",
    "تخضع هذه الشروط والسياسات وتفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية، وتختص المحاكم المختصة بالفصل في أي نزاع.",
    "يقصد بالشركة أينما وردت في هذه الشروط شركة الأفق الرقمي، ويقصد بالمستخدم كل شخص يزور المنصة أو يستفيد من خدماتها.",
    "تعود كافة حقوق الملكية الفكرية والعلامات التجارية والتصميمات الخاصة بالمنصة حصراً للشركة، ولا يجوز نسخها أو استخدامها دون إذن خطي مسبق."
  ]
}
